// Najniższy poziom regionalnej piramidy nie powinien zaczynać się dopiero
// przy 35 OVR. W każdym województwie do czterech najsłabszych dotąd klubów
// dostaje wyraźnie różne poziomy 20/23/27/30. Lubuskie ma w bazie tylko trzy
// kluby tieru 1, więc kończy na 20/23/27. Pozostałe 445 klubów tieru 1 oraz
// cała baza od IV ligi wzwyż zachowują ręcznie ustawione wartości bez zmian.
const REGIONAL_LOW_OVR_VALUES=[20,23,27,30];
REGION_NAMES.forEach(region=>{
  CLUBS
    .filter(c=>c.region===region&&c.tier===1&&!c.reserve)
    .slice()
    .sort((a,b)=>a.strength-b.strength||a.name.localeCompare(b.name,'pl'))
    .slice(0,REGIONAL_LOW_OVR_VALUES.length)
    .forEach((club,index)=>{ club.strength=REGIONAL_LOW_OVR_VALUES[index]; });
});

